mapper.sql:
WHERE ocrn_dt >= #{from} AND ocrn_dt < #{to}
AND srch_cn_exst_yn=#{hasQuery}
AND rslt_cnt=0AND rslt_cnt>0
AND ocrn_dt <= #{cutoff}

WHERE inst_id=CAST(#{organization} AS uuid)
AND bgng_dt >= #{from} AND bgng_dt < #{to}
AND type_cd=#{analysisKind}
AND stts_cd=#{status}
AND (position(#{query} in lower(id::text))>0 OR position(#{query} in lower(engn_ver_nm))>0 OR position(#{query} in lower(sou_hash_vl))>0)
AND bgng_dt <= #{cutoff} AND end_dt <= #{cutoff}

mapper.select:
SELECT id::text,dmnd_id AS request_id,ocrn_dt AS occurred_at,srch_cn_exst_yn AS has_query,nrmlz_srch_cnd_cn::text AS normalized_filters,rslt_cnt AS result_count,req_ms_cnt AS duration_ms,srch_rng_cd AS search_scope
FROM analytics.search_event 
ORDER BY ocrn_dt DESC,id LIMIT #{size} OFFSET #{offset}
